const raw = $input.item.json.output[0].content[0].text;
let cleaned = raw.replace(/```json|```/g, '').trim();

function sanitizeJson(str) {
  let result = '';
  let inString = false;
  const validEscapes = new Set(['"', '\\', '/', 'b', 'f', 'n', 'r', 't', 'u']);

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (char === '\\' && inString) {
      const nextChar = str[i + 1];
      if (validEscapes.has(nextChar)) {
        // valid escape sequence, keep both characters as-is
        result += char + nextChar;
        i++; // skip the next character, already consumed
        continue;
      } else {
        // invalid escape — double the backslash so it becomes a literal \ in the parsed string
        result += '\\\\';
        continue;
      }
    }

    if (char === '"' && str[i - 1] !== '\\') {
      inString = !inString;
      result += char;
      continue;
    }

    if (inString) {
      if (char === '\n') { result += '\\n'; continue; }
      if (char === '\r') { result += '\\r'; continue; }
      if (char === '\t') { result += '\\t'; continue; }
      const code = char.charCodeAt(0);
      if (code < 0x20) {
        result += '\\u' + code.toString(16).padStart(4, '0');
        continue;
      }
    }

    result += char;
  }
  return result;
}

cleaned = sanitizeJson(cleaned);

let site;
try {
  site = JSON.parse(cleaned);
} catch (e) {
  throw new Error(`Failed to parse site generation output: ${e.message}\nRaw: ${cleaned.slice(0, 500)}`);
}

return { json: site, pairedItem: { item: 0 } };

